package io.knowledgebrain.space;
import jakarta.servlet.http.HttpServletRequest;import java.util.*;import java.io.IOException;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.space.group-membership.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/progress-sharing-policy")
final class GroupProgressPolicyController {
 private final GroupProgressPolicyStore store;private final IdentityPrincipalClient identity;private final String origin;private final MeterRegistry metrics;
 GroupProgressPolicyController(GroupProgressPolicyStore store,IdentityPrincipalClient identity,MeterRegistry metrics,@Value("${brain.space.group-membership.browser-origin}")String origin){this.store=store;this.identity=identity;this.metrics=metrics;this.origin=origin;}
 private UUID actor(HttpServletRequest r){var p=identity.resolve(GroupBrowserRequest.token(r),GroupBrowserRequest.parent(r));if(!"REGISTERED".equals(p.kind()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Registered account required");return p.principalId();}
 static long match(HttpServletRequest r){var values=Collections.list(r.getHeaders("If-Match"));if(values.size()!=1)throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"Sharing policy version required");var value=values.getFirst();if(!value.matches("\"gpp(0|[1-9][0-9]{0,18})\""))throw GroupBrowserRequest.bad();try{return Long.parseLong(value.substring(4,value.length()-1));}catch(NumberFormatException e){throw GroupBrowserRequest.bad();}}
 private ResponseEntity<?> response(GroupProgressPolicyStore.Policy v){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"gpp"+v.version()+"\"").body(v);}
 @GetMapping ResponseEntity<?> get(@PathVariable String groupId,HttpServletRequest r)throws IOException{var actor=actor(r);GroupBrowserRequest.read(r,Set.of());metrics.counter("brain.space.group.progress.policy.reads").increment();return response(store.get(GroupBrowserRequest.id(groupId),actor));}
 @PutMapping ResponseEntity<?> change(@PathVariable String groupId,HttpServletRequest r)throws IOException{var actor=actor(r);var input=GroupBrowserRequest.write(r,origin,Set.of("mode"));var v=store.change(GroupBrowserRequest.id(groupId),actor,match(r),input.path("mode").asString(),GroupBrowserRequest.parent(r).substring(3,35));metrics.counter("brain.space.group.progress.policy.changes").increment();return response(v);}
 @GetMapping("/revisions") ResponseEntity<?> history(@PathVariable String groupId,HttpServletRequest r)throws IOException{var actor=actor(r);GroupBrowserRequest.read(r,Set.of("before","limit"));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(GroupBrowserRequest.id(groupId),actor,GroupBrowserRequest.before(r),GroupBrowserRequest.limit(r,10,5)));}
}
